const setup = tabs.find(t => t.textContent.trim()==='Setup');
setup.focus();
setup.dispatchEvent(new KeyboardEvent('keydown', {key:'ArrowRight', bubbles:true}));
await new Promise(r=>setTimeout(r,500));
const st1 = tabs.map(t=>t.textContent.trim()+':'+t.getAttribute('data-state')).join(' | ');
document.activeElement.dispatchEvent(new KeyboardEvent('keydown', {key:'ArrowRight', bubbles:true}));
await new Promise(r=>setTimeout(r,800));
const st2 = [...document.querySelectorAll('[role="tab"]')].map(t=>t.textContent.trim()+':'+t.getAttribute('data-state')).join(' | ');
const panel = [...document.querySelectorAll('[role="tabpanel"]')].find(p=>p.getAttribute('data-state')==='active');
JSON.stringify({afterFirstArrow: st1, afterSecondArrow: st2, activePanel: panel?.innerText.trim().slice(0,400)}, null, 1);

