 * Derived capability facets for a connection (or connector group). Stage 2b.
 * - `data` — ingests data into memory (feeds → events).
 * - `chat` — a live bot adapter the agent converses through.
 * - `actions` — exposes operations the agent can invoke.
 * - `audience` — read access gated by the source's own membership
 *   (Slack channel members, GitHub repo collaborators).
 */
export interface ConnectionFacets {
	data: boolean;
	chat: boolean;
	actions: boolean;
	audience: boolean;
}

export interface ConnectionItem {
	id: number;
	slug: string;
	organization_id: string;
	connector_key: string;
	display_name: string | null;
	/** Provider-side tenant this connection is scoped to (a Slack workspace, a
	 * Teams tenant, a GitHub org). Every connection is conceptually tenanted;
	 * the column is populated where routing needs it and NULL elsewhere. */
