1	import { createFileRoute, Link, useNavigate } from "@tanstack/react-router";
2	import {
3		DETAIL_BACK_LINK_CLASS,
4		DetailBackIcon,
5		DetailHeader,
6	} from "@/components/connectors/detail-header";
7	import { ConnectorPageShell } from "@/components/connectors/connector-page-shell";
8	import { FacetChips } from "@/components/connectors/facet-chips";
9	import { ActionRunner } from "@/components/entity-tabs/connections-tab/action-runner";
10	import { AddFeedForm } from "@/components/entity-tabs/connections-tab/add-feed-form";
11	import { ConnectionChannelFeed } from "@/components/entity-tabs/connections-tab/connection-channel-feed";
12	import { ConnectionFeedDetail } from "@/components/entity-tabs/connections-tab/connection-feed-detail";
13	import { ConnectionFeedsRail } from "@/components/entity-tabs/connections-tab/connection-feeds-rail";
14	import {
15		ConnectionActionsSection,
16		ConnectionSettingsTab,
17	} from "@/components/entity-tabs/connections-tab/connection-settings-tab";
18	import { DeviceFoldersPanel } from "@/components/entity-tabs/connections-tab/device-folders-panel";
19	import { OwnerWorkspaceGate } from "@/components/owner-workspace-gate";
20	import { RunsLayoutSkeleton } from "@/components/runs/runs-layout-skeleton";
21	import { RunsPanel } from "@/components/runs/runs-panel";
22	import { Badge } from "@/components/ui/badge";
23	import { Skeleton } from "@/components/ui/skeleton";
24	import { StatusBadge } from "@/components/ui/status-badge";
25	import { TabsContent } from "@/components/ui/tabs";
26	import {
27		useConnections,
28		useConnectorDefinitions,
29		useFeeds,
30	} from "@/lib/api/connections";
31	import { useWorkspaceRoot } from "@/lib/api/entities";
32	import { connectionLabel } from "@/lib/connection-label";
33	import { connectionDisplayError } from "@/lib/device-pin-tombstone";
34	import { pruneSearch } from "@/lib/router-search";
35	import { getStatusVariant } from "@/lib/status-variants";
36	
37	export const Route = createFileRoute(
38		"/$owner/connectors/$connectorKey/$connectionId",
39	)({
40		validateSearch: (search: Record<string, unknown>) =>
41			pruneSearch({
42				addFeed:
43					search.addFeed === true || search.addFeed === "true" ? true : undefined,
44				feedId:
45					typeof search.feedId === "number"
46						? search.feedId
47						: typeof search.feedId === "string" && /^\d+$/.test(search.feedId)
48							? Number(search.feedId)
49							: undefined,
50			}),
51		loaderDeps: ({ search: { feedId } }) => ({ feedId }),
52		loader: ({ context: { queryClient }, params, deps }) => {
53			// Fire-and-forget — workspace + connection prefetches warm the cache
54			// but never block paint. ConnectionDetailView renders its skeleton
55			// via isWorkspaceLoading until everything resolves. `useFeeds` is
56			// only consumed on feedId deep-links so we chain its prefetch behind
57			// workspace too.
58			void queryClient
59				.fetchQuery(
60					useWorkspaceRoot.queryOptions(params.owner, { slug: params.owner }),
61				)
62				.then((ws) => {
63					const orgId = ws?.workspace?.id;
64					if (!orgId) return;
65					void queryClient.prefetchQuery(
66						useConnections.queryOptions(orgId, {
67							connectorKey: params.connectorKey,
68						}),
69					);
70					void queryClient.prefetchQuery(
71						useConnectorDefinitions.queryOptions(orgId),
72					);
73					if (deps.feedId !== undefined) {
74						void queryClient.prefetchQuery(
75							useFeeds.queryOptions(Number(params.connectionId)),
76						);
77					}
78				})
79				.catch(() => {
80					// Page handles missing-workspace; swallow loader errors here.
81				});
82		},
83		component: ConnectionDetailRoute,
84	});
85	
86	function ConnectionDetailRoute() {
87		const { owner, connectorKey, connectionId } = Route.useParams();
88		const { addFeed, feedId } = Route.useSearch();
89		return (
90			<OwnerWorkspaceGate owner={owner}>
91				{(props) => (
92					<ConnectionDetailView
93						organizationId={props.organizationId}
94						ownerSlug={props.ownerSlug}
95						isWorkspaceLoading={props.isWorkspaceLoading}
96						connectorKey={connectorKey}
97						connectionId={Number(connectionId)}
98						showAddFeed={addFeed === true}
99						feedId={feedId}
100					/>
101				)}
102			</OwnerWorkspaceGate>
103		);
104	}
