import { createFileRoute, Link, useNavigate } from "@tanstack/react-router";
import { ConnectorPageShell } from "@/components/connectors/connector-page-shell";
import {
	DETAIL_BACK_LINK_CLASS,
	DetailBackIcon,
	DetailHeader,
} from "@/components/connectors/detail-header";
import { FacetChips } from "@/components/connectors/facet-chips";
import { ActionRunner } from "@/components/entity-tabs/connections-tab/action-runner";
import { AddFeedForm } from "@/components/entity-tabs/connections-tab/add-feed-form";
import { ConnectionChannelFeed } from "@/components/entity-tabs/connections-tab/connection-channel-feed";
import { ConnectionFeedDetail } from "@/components/entity-tabs/connections-tab/connection-feed-detail";
import { ConnectionFeedsRail } from "@/components/entity-tabs/connections-tab/connection-feeds-rail";
import {
	ConnectionActionsSection,
	ConnectionSettingsTab,
} from "@/components/entity-tabs/connections-tab/connection-settings-tab";
import { DeviceFoldersPanel } from "@/components/entity-tabs/connections-tab/device-folders-panel";
import { OwnerWorkspaceGate } from "@/components/owner-workspace-gate";
import { RunsLayoutSkeleton } from "@/components/runs/runs-layout-skeleton";
import { RunsPanel } from "@/components/runs/runs-panel";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { StatusBadge } from "@/components/ui/status-badge";
import { TabsContent } from "@/components/ui/tabs";
import {
	useConnections,
	useConnectorDefinitions,
	useFeeds,
} from "@/lib/api/connections";
import { useWorkspaceRoot } from "@/lib/api/entities";
import { connectionLabel } from "@/lib/connection-label";
import { connectionDisplayError } from "@/lib/device-pin-tombstone";
import { pruneSearch } from "@/lib/router-search";
import { getStatusVariant } from "@/lib/status-variants";

export const Route = createFileRoute(
	"/$owner/connectors/$connectorKey/$connectionId",
)({
	validateSearch: (search: Record<string, unknown>) =>
		pruneSearch({
			addFeed:
				search.addFeed === true || search.addFeed === "true" ? true : undefined,
			feedId:
				typeof search.feedId === "number"
					? search.feedId
					: typeof search.feedId === "string" && /^\d+$/.test(search.feedId)
						? Number(search.feedId)
						: undefined,
		}),
	loaderDeps: ({ search: { feedId } }) => ({ feedId }),
	loader: ({ context: { queryClient }, params, deps }) => {
		// Fire-and-forget — workspace + connection prefetches warm the cache
		// but never block paint. ConnectionDetailView renders its skeleton
		// via isWorkspaceLoading until everything resolves. `useFeeds` is
		// only consumed on feedId deep-links so we chain its prefetch behind
		// workspace too.
		void queryClient
			.fetchQuery(
				useWorkspaceRoot.queryOptions(params.owner, { slug: params.owner }),
			)
			.then((ws) => {
				const orgId = ws?.workspace?.id;
				if (!orgId) return;
				void queryClient.prefetchQuery(
					useConnections.queryOptions(orgId, {
						connectorKey: params.connectorKey,
					}),
				);
				void queryClient.prefetchQuery(
					useConnectorDefinitions.queryOptions(orgId),
				);
				if (deps.feedId !== undefined) {
					void queryClient.prefetchQuery(
						useFeeds.queryOptions(Number(params.connectionId)),
					);
				}
			})
			.catch(() => {
				// Page handles missing-workspace; swallow loader errors here.
			});
	},
	component: ConnectionDetailRoute,
});

function ConnectionDetailRoute() {
	const { owner, connectorKey, connectionId } = Route.useParams();
	const { addFeed, feedId } = Route.useSearch();
	return (
		<OwnerWorkspaceGate owner={owner}>
			{(props) => (
				<ConnectionDetailView
					organizationId={props.organizationId}
					ownerSlug={props.ownerSlug}
					isWorkspaceLoading={props.isWorkspaceLoading}
					connectorKey={connectorKey}
					connectionId={Number(connectionId)}
					showAddFeed={addFeed === true}
					feedId={feedId}
				/>
			)}
		</OwnerWorkspaceGate>
	);
}

/** Human-readable credential-mode badge text, or null when unresolved. */
const CREDENTIAL_MODE_LABEL = {
	managed: "Managed",
	byo: "BYO",
} as const;

function ConnectionDetailView({
	organizationId,
	ownerSlug,
	isWorkspaceLoading,
	connectorKey,
	connectionId,
	showAddFeed,
	feedId,
}: {
	organizationId: string | null;
	ownerSlug: string;
	isWorkspaceLoading: boolean;
	connectorKey: string;
	connectionId: number;
	showAddFeed: boolean;
	feedId: number | undefined;
}) {
	const navigate = useNavigate();
	const { data: connections = [], isLoading } = useConnections(
		organizationId ?? "",
		{ connectorKey },
	);
	const { data: connectorDefs = [] } = useConnectorDefinitions(
		organizationId ?? "",
	);
	const { data: feeds = [] } = useFeeds(feedId ? connectionId : null);
	const connection = connections.find((c) => c.id === connectionId);
	const connectorDef = connectorDefs.find((d) => d.key === connectorKey);
	const feed = feedId ? feeds.find((f) => f.id === feedId) : null;

	if (isWorkspaceLoading || isLoading || !organizationId) {
		// Chrome-paint-first: render name + breadcrumb skeletons in the same
		// position the loaded chrome will occupy, plus the two-column
		// runs-left / form-right skeleton for the body, so nothing reflows
		// when data lands.
		return (
			<div className="flex flex-1 flex-col gap-4">
				<div className="flex flex-wrap items-baseline gap-x-3 gap-y-1">
					<Skeleton className="h-7 w-56" />
					<Skeleton className="h-4 w-24" />
				</div>
				<RunsLayoutSkeleton />
			</div>
		);
	}
	if (!connection) {
		return (
			<div>
				<p className="text-sm text-muted-foreground">Connection not found.</p>
				<Link
					to="/$owner/connectors/$connectorKey"
					params={{ owner: ownerSlug, connectorKey }}
					className="mt-2 inline-block text-sm text-primary hover:underline"
				>
					Back to {connectorDef?.name ?? connectorKey}
				</Link>
			</div>
		);
	}

	const displayName = connectionLabel({
		...connection,
		connector_name: connection.connector_name ?? connectorDef?.name ?? null,
	});

	const credentialMode = connection.effective_credential_mode
		? CREDENTIAL_MODE_LABEL[connection.effective_credential_mode]
		: null;

	// Facet-aware layout: a chat connection (a live bot adapter) has no sync
	// runs / run-on-device target / entity tagging — those are data-connector
	// chrome — so its main pane is just settings. But its channels ARE streaming
	// feeds, so it still gets the feeds rail (see showRail below).
	const isChat = connection.facets?.chat ?? false;

	const goToConnection = () =>
		void navigate({
			to: "/$owner/connectors/$connectorKey/$connectionId",
			params: {
				owner: ownerSlug,
				connectorKey,
				connectionId: String(connectionId),
			},
			search: {},
			replace: true,
		});

	// Main pane modes: feed detail > add feed form > connection settings.
	// The feeds rail sits on the left for the feed-detail and settings modes
	// (mirroring the memory page); the focused add-feed form skips it. A
	// connection with no feeds keeps the old full-width layout — an empty rail
	// would just be chrome.
	// A chat connection's channels are streaming feeds, so it gets the same
	// rail as a data connection — channels render as feed rows under the
	// connection (one unified surface), not a bespoke channel tree.
	const showRail = !showAddFeed && (connection.feed_count ?? 0) > 0;
	const isDefaultMode = !feedId && !showAddFeed;
	let mainPane: React.ReactNode;
	let subTitle = connectorDef?.name ?? connection.connector_key;

	if (feedId) {
		if (!feed) {
			mainPane = (
				<p className="text-sm text-muted-foreground">Feed not found.</p>
			);
		} else if (feed.kind === "streaming") {
			// A chat channel is a streaming feed: its detail is the conversation
			// (channel_messages lens), not a runs table.
			mainPane = <ConnectionChannelFeed feed={feed} onClose={goToConnection} />;
			subTitle = `${subTitle} · Channel`;
		} else {
			mainPane = (
				<ConnectionFeedDetail
					feed={feed}
					connectorDef={connectorDef}
					ownerSlug={ownerSlug}
					onClose={goToConnection}
					// Parent sticky header already links back to the connection.
					showBack={false}
				/>
			);
			subTitle = `${subTitle} · Feed`;
		}
	} else if (showAddFeed) {
		mainPane = (
			<AddFeedForm
				onClose={goToConnection}
				organizationId={organizationId}
				connections={[connection]}
				connectorDefinitions={connectorDefs}
			/>
		);
		subTitle = `${subTitle} · Add feed`;
	}

	const header = (
		<DetailHeader
			back={
				<Link
					to="/$owner/connectors/$connectorKey"
					params={{ owner: ownerSlug, connectorKey }}
					className={DETAIL_BACK_LINK_CLASS}
				>
					<DetailBackIcon />
					{connectorDef?.name ?? connectorKey}
				</Link>
			}
			title={
				feedId ? (
					<Link
						to="/$owner/connectors/$connectorKey/$connectionId"
						params={{
							owner: ownerSlug,
							connectorKey,
							connectionId: String(connectionId),
						}}
						search={{}}
						className="text-2xl font-semibold leading-tight hover:underline"
					>
						{displayName}
					</Link>
				) : (
					displayName
				)
			}
			subtitle={subTitle}
			status={
				<StatusBadge status={getStatusVariant(connection.status)} showDot>
					{connection.status}
				</StatusBadge>
			}
			chips={
				connection.facets || credentialMode ? (
					<>
						<FacetChips facets={connection.facets} />
						{credentialMode ? (
							<Badge
								variant="outline"
								className="border-border text-muted-foreground"
							>
								{credentialMode}
							</Badge>
						) : null}
					</>
				) : null
			}
			error={connectionDisplayError(connection)}
		/>
	);

	if (isDefaultMode) {
		const showActivity = !isChat;
		const showActions = connection.has_operations === true;
		const defaultTab = showActivity ? "activity" : "settings";
		return (
			<ConnectorPageShell
				header={header}
				tabs={[
					...(showActivity ? [{ value: "activity", label: "Activity" }] : []),
					...(showActions ? [{ value: "actions", label: "Actions" }] : []),
					{ value: "settings", label: "Settings" },
				]}
				defaultTab={defaultTab}
				rail={
					showRail ? (
						<ConnectionFeedsRail
							connection={connection}
							ownerSlug={ownerSlug}
							activeFeedId={feedId}
						/>
					) : undefined
				}
				width="6xl"
			>
				{connectorKey === "local.directory" && (
					<DeviceFoldersPanel connectionId={connectionId} />
				)}
				{showActivity ? (
					<TabsContent value="activity" className="mt-0">
						<RunsPanel scope={{ connectionId }} ownerSlug={ownerSlug} />
					</TabsContent>
				) : null}
				{showActions ? (
					<TabsContent value="actions" className="mt-0 space-y-6">
						<ConnectionActionsSection connection={connection} />
						<ActionRunner connectionId={connectionId} />
					</TabsContent>
				) : null}
				<TabsContent value="settings" className="mt-0">
					<div className="max-w-3xl">
						<ConnectionSettingsTab
							connection={connection}
							connectorDef={connectorDef}
							ownerSlug={ownerSlug}
						/>
					</div>
				</TabsContent>
			</ConnectorPageShell>
		);
	}

	// Feed detail / add-feed: no tab bar at all, so the shell renders header +
	// rail + pane without a TabsList. The focused add-feed form drops the rail
	// and narrows the column.
	return (
		<ConnectorPageShell
			header={header}
			rail={
				showRail ? (
					<ConnectionFeedsRail
						connection={connection}
						ownerSlug={ownerSlug}
						activeFeedId={feedId}
					/>
				) : undefined
			}
			width={showAddFeed ? "3xl" : "6xl"}
		>
			{mainPane}
		</ConnectorPageShell>
	);
}

import type { ReactNode } from "react";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { cn } from "@/lib/utils";

/**
 * Page chrome shared by the connector-detail and connection-detail routes:
 * a sticky header, an optional tab bar, an optional left rail, and the content
 * pane. Both routes grew the same shape independently and drifted — three
 * different width rules (max-w-3xl / unconstrained / max-w-6xl) and two header
 * spacings across two files. Centralising the chrome makes that drift
 * impossible; the routes still own their own tabs, rails and content.
 *
 * `tabs` is optional because the feed-detail mode has no tab bar at all, and
 * `rail` is optional because a connector with no connections (or a connection
 * with no feeds) renders a bare column.
 */
export interface ConnectorPageTab {
	value: string;
	label: string;
	/** Tab body. Rendered by the caller inside <TabsContent>. */
	content: ReactNode;
}

export function ConnectorPageShell({
	header,
	tabs,
	defaultTab,
	rail,
	width = "3xl",
	children,
}: {
	/** Breadcrumb + title block. Always sticky. */
	header: ReactNode;
	/** Tab triggers, in order. Omit for modes with no tab bar (feed detail). */
	tabs?: { value: string; label: string }[];
	defaultTab?: string;
	/** Left rail — connections or feeds. Omit when there's nothing to list. */
	rail?: ReactNode;
	/**
	 * Content column width. A rail needs the wider column to sit beside;
	 * a bare column stays narrow so prose doesn't run long.
	 */
	width?: "3xl" | "6xl";
	children: ReactNode;
}) {
	// One sticky treatment for both routes — previously space-y-3 here and
	// space-y-2 on the connection page, for no reason anyone could name.
	const sticky = cn(
		"sticky top-11 z-10 -mx-4 bg-background px-4 pt-1 lg:-mx-6 lg:px-6",
		tabs ? "pb-0" : "pb-3",
	);
	// The sticky background bleeds full-width (-mx) while its contents align to
	// the same column as the body, so header, tabs and content share one left
	// edge instead of the header running full-bleed over a centred column.
	const column = cn(
		"mx-auto w-full",
		width === "6xl" ? "max-w-6xl" : "max-w-3xl",
	);

	const body = (
		<div
			className={cn(
				"mt-6 gap-6",
				column,
				rail ? "flex flex-col lg:flex-row lg:items-start" : null,
			)}
		>
			{rail}
			{/* Never a full-height flex column: that lets an empty state's
			    justify-center float mid-page with dead space below it. */}
			<div className={cn("min-w-0 space-y-6", rail ? "flex-1" : null)}>
				{children}
			</div>
		</div>
	);

	if (!tabs) {
		return (
			<div className="flex flex-1 flex-col">
				<div className={sticky}>
					<div className={cn("space-y-3", column)}>{header}</div>
				</div>
				{body}
			</div>
		);
	}

	return (
		<div className="flex flex-1 flex-col">
			<Tabs
				defaultValue={defaultTab ?? tabs[0]?.value}
				className="flex min-h-0 flex-1 flex-col"
			>
				<div className={sticky}>
					<div className={cn("space-y-3", column)}>
						{header}
						<TabsList>
							{tabs.map((tab) => (
								<TabsTrigger key={tab.value} value={tab.value}>
									{tab.label}
								</TabsTrigger>
							))}
						</TabsList>
					</div>
				</div>
				{body}
			</Tabs>
		</div>
	);
}

