import type { ReactNode } from "react";

/** Shared class for the `← Parent` back-link/button so every detail page's
 * back affordance is styled identically. Use on a router <Link> or a <button>. */
export const DETAIL_BACK_LINK_CLASS =
	"inline-flex w-fit items-center gap-1 text-xs text-muted-foreground transition-colors hover:text-foreground";

/** The leading arrow icon for a back affordance. */
export function DetailBackIcon() {
	return <ArrowLeft className="h-3 w-3" />;
}

/**
 * Shared header for the connector / connection / feed detail pages so all three
 * levels look identical: a back-link row, then a title row (title · subtitle ·
 * status, baseline-aligned), then an optional chips row, then an optional error
 * banner. Each page passes its own slots; the layout is the single source of
 * truth so spacing and alignment never drift between pages.
 *
 * `back` is rendered as a plain element (a router Link or a button) so callers
 * can navigate by route or by an onClose callback without this component
 * knowing about either.
 */
export function DetailHeader({
	back,
	title,
	subtitle,
	status,
	chips,
	meta,
	error,
}: {
	/** The `← Parent` affordance. A router <Link> or a <button onClick={onClose}>. */
	back?: ReactNode;
	/** The primary heading — a string, or a <Link>-wrapped string for feeds. */
	title: ReactNode;
	/** Muted secondary label next to the title (e.g. the connector name). */
	subtitle?: ReactNode;
	/** Status badge shown inline after the subtitle. */
	status?: ReactNode;
	/** Capability/credential chips row (e.g. FacetChips + credential badge). */
	chips?: ReactNode;
	/** Right-aligned metadata on the title row (e.g. sync/next/events stats). */
	meta?: ReactNode;
	/** Error banner shown below the header when the entity is in an error state. */
	error?: ReactNode;
}) {
	return (
		<div className="flex flex-col gap-2">
			{back ? <div className="flex">{back}</div> : null}
			<div className="flex flex-wrap items-baseline justify-between gap-x-3 gap-y-1">
				<div className="flex flex-wrap items-baseline gap-x-3 gap-y-1">
					{typeof title === "string" ? (
						<h1 className="text-2xl font-semibold leading-tight">{title}</h1>
					) : (
						title
					)}
					{subtitle ? (
						<span className="text-sm text-muted-foreground">{subtitle}</span>
					) : null}
					{status}
				</div>
				{meta ? (
					<div className="flex flex-wrap items-center gap-x-4 gap-y-1 text-xs text-muted-foreground">
						{meta}
					</div>
				) : null}
			</div>
			{chips ? (
				<div className="flex flex-wrap items-center gap-1">{chips}</div>
			) : null}
			{error ? <p className="text-sm text-destructive">{error}</p> : null}
		</div>
	);
}

