199		// Main pane modes: feed detail > add feed form > connection settings.
200		// The feeds rail sits on the left for the feed-detail and settings modes
201		// (mirroring the memory page); the focused add-feed form skips it. A
202		// connection with no feeds keeps the old full-width layout — an empty rail
203		// would just be chrome.
204		// A chat connection's channels are streaming feeds, so it gets the same
205		// rail as a data connection — channels render as feed rows under the
206		// connection (one unified surface), not a bespoke channel tree.
207		const showRail = !showAddFeed && (connection.feed_count ?? 0) > 0;
208		const isDefaultMode = !feedId && !showAddFeed;
209		let mainPane: React.ReactNode;
210		let subTitle = connectorDef?.name ?? connection.connector_key;
211	
212		if (feedId) {
213			if (!feed) {
214				mainPane = (
215					<p className="text-sm text-muted-foreground">Feed not found.</p>
216				);
217			} else if (feed.kind === "streaming") {
218				// A chat channel is a streaming feed: its detail is the conversation
