import { getStatusVariant } from "@/lib/status-variants";
import { DynamicConnectorForm } from "./dynamic-connector-form";

const REPAIR_MAX_ATTEMPTS = 5;

function feedDisplayName(
	feed: FeedItem,
	connectorDef?: ConnectorDefinitionItem,
): string {
	if (feed.display_name) return feed.display_name;
	const def = connectorDef?.feeds_schema?.[feed.feed_key] as
		| { name?: string }
		| undefined;
	return def?.name ?? feed.feed_key;
}

function getFeedConfigSchema(
	connectorDef: ConnectorDefinitionItem | undefined,
	feedKey: string,
): Record<string, unknown> | undefined {
	const feedsSchema = connectorDef?.feeds_schema as Record<
		string,
		{ key?: string; configSchema?: Record<string, unknown> }
	> | null;
	if (!feedsSchema) return undefined;

