import { Link } from "@tanstack/react-router";
import { AlertCircle, Pause, Play, RefreshCw } from "lucide-react";
import { useCallback, useEffect, useMemo, useState } from "react";
import { RepairAgentPicker } from "@/components/repair-agent-picker";
import { RunsTable } from "@/components/runs/runs-table";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Spinner } from "@/components/ui/spinner";
import { StatusBadge } from "@/components/ui/status-badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { ViewInMemoryLink } from "@/components/view-in-memory-link";
import type { ConnectorDefinitionItem, FeedItem } from "@/lib/api";
import {
	useAgents,
	useFeedDetail,
	useTriggerFeed,
	useUpdateFeed,
} from "@/lib/api";
import { formatShortDate, formatTimeAgo } from "@/lib/format-utils";
import { getStatusVariant } from "@/lib/status-variants";
import { DynamicConnectorForm } from "./dynamic-connector-form";

const REPAIR_MAX_ATTEMPTS = 5;

/** The feed's own name — also used by the connection route's breadcrumb, so
 * the trail's last segment matches the heading below it. */
export function feedDisplayName(
	feed: FeedItem,
	connectorDef?: ConnectorDefinitionItem,
): string {
	if (feed.display_name) return feed.display_name;
	const def = connectorDef?.feeds_schema?.[feed.feed_key] as
		| { name?: string }
		| undefined;
	return def?.name ?? feed.feed_key;
}

function getFeedConfigSchema(
	connectorDef: ConnectorDefinitionItem | undefined,
	feedKey: string,
): Record<string, unknown> | undefined {
	const feedsSchema = connectorDef?.feeds_schema as Record<
		string,
		{ key?: string; configSchema?: Record<string, unknown> }
	> | null;
	if (!feedsSchema) return undefined;

	if (feedsSchema[feedKey]?.configSchema)
		return feedsSchema[feedKey].configSchema;

	for (const entry of Object.values(feedsSchema)) {
		if (entry?.key === feedKey && entry.configSchema) return entry.configSchema;
	}

	const entries = Object.values(feedsSchema);
	if (entries.length === 1 && entries[0]?.configSchema)
		return entries[0].configSchema;

	return undefined;
}

/** Feed status badges for the page header. Lives here (not on the route) so the
 * feed's status vocabulary stays with the feed pane that owns it. */
export function FeedStatusBadges({
	feed,
	ownerSlug,
}: {
	feed: FeedItem;
	ownerSlug: string;
}) {
	return (
		<>
			<StatusBadge status={getStatusVariant(feed.status)} showDot>
				{feed.status}
			</StatusBadge>
			{feed.connection_status && feed.connection_status !== feed.status && (
				<StatusBadge status={getStatusVariant(feed.connection_status)} showDot>
					Connection: {feed.connection_status}
				</StatusBadge>
			)}
			{feed.device_worker_id ? (
				<Link
					to="/$owner/infrastructure/devices/$deviceId"
					params={{ owner: ownerSlug, deviceId: feed.device_worker_id }}
				>
					<Badge
						variant={feed.device_status === "offline" ? "secondary" : "outline"}
						className="text-xs hover:bg-accent"
					>
						{feed.device_status === "offline"
							? `Waiting for ${feed.device_label || feed.device_platform || "device"}`
							: `On ${feed.device_label || feed.device_platform || "device"}`}
					</Badge>
				</Link>
			) : null}
		</>
	);
}

/** Sync/next/event-count stats for the page header's right-aligned meta slot. */
export function FeedHeaderMeta({ feed }: { feed: FeedItem }) {
	return (
		<>
			<span>
				Last sync: {feed.last_sync_at ? formatTimeAgo(feed.last_sync_at) : "—"}
			</span>
			<span>Next: {feed.next_run_at ? formatTimeAgo(feed.next_run_at) : "—"}</span>
			<span className="font-mono">
				{(feed.event_count ?? 0).toLocaleString()} events
			</span>
		</>
	);
}

export function ConnectionFeedDetail({
	feed,
	connectorDef,
	ownerSlug,
}: {
	feed: FeedItem;
	connectorDef?: ConnectorDefinitionItem;
	ownerSlug: string;
}) {
	const { data: feedDetail, refetch } = useFeedDetail(feed.id);
	const updateFeed = useUpdateFeed();
	const triggerFeed = useTriggerFeed();
	const { data: agents = [] } = useAgents();

	const hasActiveRun = feedDetail?.recent_runs?.some((r) =>
		["running", "pending", "claimed"].includes(r.status),
	);
	useEffect(() => {
		if (!hasActiveRun) return;
		const id = setInterval(() => refetch(), 5000);
		return () => clearInterval(id);
	}, [hasActiveRun, refetch]);

	const [configValues, setConfigValues] = useState<Record<string, unknown>>(
		feed.config ?? {},
	);
	const [dirty, setDirty] = useState(false);

	const configSchema = useMemo(
		() => getFeedConfigSchema(connectorDef, feed.feed_key),
		[connectorDef, feed.feed_key],
	);

	const connectorDefaultRepairAgentId =
		connectorDef?.default_repair_agent_id ?? null;
	const connectorDefaultRepairAgentName = useMemo(() => {
		if (!connectorDefaultRepairAgentId) return null;
		return (
			agents.find((a) => a.agentId === connectorDefaultRepairAgentId)?.name ??
			connectorDefaultRepairAgentId
		);
	}, [agents, connectorDefaultRepairAgentId]);

	const handleRepairAgentChange = useCallback(
		(next: string | null) => {
			void updateFeed.mutateAsync({ feed_id: feed.id, repair_agent_id: next });
		},
		[updateFeed, feed.id],
	);

	const handleConfigChange = useCallback((values: Record<string, unknown>) => {
		setConfigValues(values);
		setDirty(true);
	}, []);

	const handleSave = useCallback(async () => {
		await updateFeed.mutateAsync({ feed_id: feed.id, config: configValues });
		setDirty(false);
	}, [updateFeed, feed.id, configValues]);

	const handleToggleStatus = useCallback(async () => {
		const nextStatus = feed.status === "active" ? "paused" : "active";
		await updateFeed.mutateAsync({ feed_id: feed.id, status: nextStatus });
	}, [updateFeed, feed.id, feed.status]);

	const handleTrigger = useCallback(async () => {
		await triggerFeed.mutateAsync(feed.id);
	}, [triggerFeed, feed.id]);

	const isActive = feed.status === "active";
	const authIssue =
		feed.auth_profile_status && feed.auth_profile_status !== "active";
	const isBusy = updateFeed.isPending || triggerFeed.isPending;

	return (
		<div className="space-y-4">
			<div className="flex flex-wrap items-center gap-2">
				<Button
					variant="outline"
					size="sm"
					disabled={isBusy}
					onClick={() => void handleToggleStatus()}
				>
					{isActive ? (
						<Pause className="h-3.5 w-3.5 mr-1.5" />
					) : (
						<Play className="h-3.5 w-3.5 mr-1.5" />
					)}
					{isActive ? "Pause" : "Resume"}
				</Button>

				<div className="min-w-[220px] max-w-xs">
					<RepairAgentPicker
						value={feed.repair_agent_id}
						onChange={handleRepairAgentChange}
						disabled={updateFeed.isPending}
						emptyLabel={
							connectorDefaultRepairAgentName
								? `Repair: inherit (${connectorDefaultRepairAgentName})`
								: "Repair: none"
						}
					/>
				</div>

				<Button
					variant="outline"
					size="sm"
					disabled={isBusy || !isActive}
					onClick={() => void handleTrigger()}
				>
					{triggerFeed.isPending ? (
						<Spinner size="md" className="mr-1.5" />
					) : (
						<RefreshCw className="h-3.5 w-3.5 mr-1.5" />
					)}
					Sync now
				</Button>

				<ViewInMemoryLink
					ownerSlug={ownerSlug}
					scope={{ kind: "feed", id: feed.id }}
					variant="ghost"
					label="View in memory"
				/>
			</div>

			{authIssue && (
				<div className="flex items-center gap-2 rounded-lg bg-amber-50 dark:bg-amber-950/20 px-3 py-2 text-sm">
					<AlertCircle className="h-4 w-4 text-amber-500 shrink-0" />
					<span className="text-amber-700 dark:text-amber-400">
						Authentication issue: {feed.auth_profile_status}
					</span>
					<Button
						variant="outline"
						size="sm"
						className="ml-auto h-7 text-xs"
						onClick={onClose}
					>
						Fix auth
					</Button>
				</div>
			)}

			{feed.repair_thread_id && (
				<div className="rounded-lg border bg-muted/30 px-3 py-2 text-xs">
					<div className="flex items-center justify-between gap-2">
						<span className="text-foreground">
							Repair thread open · attempt {feed.repair_attempt_count}/
							{REPAIR_MAX_ATTEMPTS}
						</span>
						{feed.last_repair_at && (
							<span
								className="text-muted-foreground"
								title={formatShortDate(feed.last_repair_at)}
							>
								{formatTimeAgo(feed.last_repair_at)}
							</span>
						)}
					</div>
					<p className="mt-1 text-muted-foreground">
						Thread id:{" "}
						<span className="font-mono text-foreground">
							{feed.repair_thread_id}
						</span>
					</p>
				</div>
			)}

			<Tabs defaultValue="activity" className="space-y-4">
				<TabsList>
					<TabsTrigger value="activity">Activity</TabsTrigger>
					<TabsTrigger value="settings">Settings</TabsTrigger>
				</TabsList>

				<TabsContent value="activity">
					{feedDetail?.recent_runs && feedDetail.recent_runs.length > 0 ? (
						<RunsTable runs={feedDetail.recent_runs} ownerSlug={ownerSlug} />
					) : (
						<p className="rounded-lg border bg-muted/20 px-3 py-6 text-center text-xs text-muted-foreground">
							No syncs yet.
						</p>
					)}
				</TabsContent>

				<TabsContent value="settings">
					<div className="max-w-xl space-y-4">
						{configSchema ? (
							<DynamicConnectorForm
								schema={configSchema}
								initialValues={feed.config ?? undefined}
								onValuesChange={handleConfigChange}
							/>
						) : (
							<p className="text-sm text-muted-foreground">
								This feed has no configurable parameters.
							</p>
						)}
						{configSchema && dirty && (
							<div className="flex justify-end">
								<Button
									size="sm"
									disabled={isBusy}
									onClick={() => void handleSave()}
								>
									{updateFeed.isPending ? (
										<Spinner size="md" className="mr-1.5" />
									) : null}
									Save
								</Button>
							</div>
						)}
					</div>
				</TabsContent>
			</Tabs>
		</div>
	);
}

