42	export const Route = createFileRoute(
43		"/$owner/connectors/$connectorKey/$connectionId",
44	)({
45		validateSearch: (search: Record<string, unknown>) =>
46			pruneSearch({
47				addFeed:
48					search.addFeed === true || search.addFeed === "true" ? true : undefined,
49				feedId:
50					typeof search.feedId === "number"
51						? search.feedId
52						: typeof search.feedId === "string" && /^\d+$/.test(search.feedId)
53							? Number(search.feedId)
54							: undefined,
55			}),
56		loaderDeps: ({ search: { feedId } }) => ({ feedId }),
57		loader: ({ context: { queryClient }, params, deps }) => {
58			// Fire-and-forget — workspace + connection prefetches warm the cache
59			// but never block paint. ConnectionDetailView renders its skeleton
60			// via isWorkspaceLoading until everything resolves. `useFeeds` is
61			// only consumed on feedId deep-links so we chain its prefetch behind
62			// workspace too.
63			void queryClient
64				.fetchQuery(
65					useWorkspaceRoot.queryOptions(params.owner, { slug: params.owner }),
66				)
67				.then((ws) => {
68					const orgId = ws?.workspace?.id;
69					if (!orgId) return;
70					void queryClient.prefetchQuery(
71						useConnections.queryOptions(orgId, {
72							connectorKey: params.connectorKey,
73						}),
74					);
75					void queryClient.prefetchQuery(
76						useConnectorDefinitions.queryOptions(orgId),
77					);
78					if (deps.feedId !== undefined) {
79						void queryClient.prefetchQuery(
80							useFeeds.queryOptions(Number(params.connectionId)),
81						);
82					}
83				})
84				.catch(() => {
85					// Page handles missing-workspace; swallow loader errors here.
86				});
87		},
88		component: ConnectionDetailRoute,
89	});
