99						ownerSlug={props.ownerSlug}
100						isWorkspaceLoading={props.isWorkspaceLoading}
101						connectorKey={connectorKey}
102						connectionId={Number(connectionId)}
103						showAddFeed={addFeed === true}
104						feedId={feedId}
105					/>
106				)}
107			</OwnerWorkspaceGate>
108		);
109	}
110	
111	/** Human-readable credential-mode badge text, or null when unresolved. */
112	const CREDENTIAL_MODE_LABEL = {
113		managed: "Managed",
114		byo: "BYO",
115	} as const;
