148			// Chrome-paint-first: render name + breadcrumb skeletons in the same
149			// position the loaded chrome will occupy, plus the two-column
150			// runs-left / form-right skeleton for the body, so nothing reflows
151			// when data lands.
152			return (
153				<div className="flex flex-1 flex-col gap-4">
154					<div className="flex flex-wrap items-baseline gap-x-3 gap-y-1">
155						<Skeleton className="h-7 w-56" />
156						<Skeleton className="h-4 w-24" />
157					</div>
158					<RunsLayoutSkeleton />
159				</div>
160			);
161		}
