const col = document.querySelector('nav[aria-label="Breadcrumb"]')?.closest('.mx-auto');
JSON.stringify({
  clicked,
  url: location.pathname + location.search,
  tabs: [...document.querySelectorAll('[role=tab]')].map(t => t.innerText),
  tablistTop: tabsEl ? Math.round(tabsEl.getBoundingClientRect().top) : null,
  railPresent: !!rail,
  railWidth: rail ? Math.round(rail.getBoundingClientRect().width) : 0,
  railLeft: rail ? Math.round(rail.getBoundingClientRect().left) : null,
  colWidth: col ? Math.round(col.getBoundingClientRect().width) : null,
  colLeft: col ? Math.round(col.getBoundingClientRect().left) : null,
}, null, 1);

