import { createFileRoute, Link, useNavigate } from "@tanstack/react-router";
import { ExternalLink, KeyRound, Plug, Plus, Search } from "lucide-react";
import { useMemo, useState } from "react";
import { AppInstallButton } from "@/components/connectors/app-install";
import {
	ConnectorDisplay,
	resolveConnectorDisplay,
} from "@/components/connectors/connector-display";
import { ConnectorPageShell } from "@/components/connectors/connector-page-shell";
import {
	DETAIL_CRUMB_LINK_CLASS,
	DetailBreadcrumb,
	DetailHeader,
} from "@/components/connectors/detail-header";
import {
	buildInstallAuthSchemaForMethod,
	buildRequestedOAuthScopes,
	getAppInstallMethod,
	getSelectableMethods,
	type OAuthMethod,
} from "@/components/entity-tabs/connections-tab/auth-helpers";
import { RAIL_SEARCH_THRESHOLD } from "@/components/entity-tabs/connections-tab/connection-feeds-rail";
import {
	type ActionMode,
	ActionsEditor,
	readActionModes,
} from "@/components/entity-tabs/connections-tab/connector-panels";
import { DynamicConnectorForm } from "@/components/entity-tabs/connections-tab/dynamic-connector-form";
import { TabEmptyState } from "@/components/entity-tabs/tab-states";
import { OwnerWorkspaceGate } from "@/components/owner-workspace-gate";
import { StatusDot } from "@/components/sidebar/status-dot";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Skeleton } from "@/components/ui/skeleton";
import { Spinner } from "@/components/ui/spinner";
import { TabsContent } from "@/components/ui/tabs";
import { useMembers } from "@/hooks/use-members";
import {
	type AuthProfileItem,
	type ConnectionItem,
	type ConnectorDefinitionItem,
	useAuthProfiles,
	useConnections,
	useConnectorOperations,
	useCreateAuthProfile,
	useCreateConnection,
	useInstallableConnectorCatalog,
	useReconnectAuthProfile,
	useSetDefaultAuthProfile,
	useUpdateConnectorDefaultConfig,
} from "@/lib/api/connections";
import { useWorkspaceRoot } from "@/lib/api/entities";
import { connectionLabel } from "@/lib/connection-label";
import { cn, FILLED_BOX } from "@/lib/utils";

export const Route = createFileRoute("/$owner/connectors/$connectorKey/")({
	// Fire-and-forget prefetch — workspace warms the cache, the page mounts
	// on the first frame and ConnectorBody renders its own skeleton while
	// workspace + connector defs resolve. The connector-defs/connections
	// prefetches can only fire once workspace lands (they need orgId), so we
	// chain them via `.then` instead of awaiting — all happen, none block paint.
	loader: ({ context: { queryClient }, params }) => {
		void queryClient
			.fetchQuery(
				useWorkspaceRoot.queryOptions(params.owner, { slug: params.owner }),
			)
			.then((ws) => {
				const orgId = ws?.workspace?.id;
				if (orgId) {
					void queryClient.prefetchQuery(
						useInstallableConnectorCatalog.queryOptions(orgId),
					);
					void queryClient.prefetchQuery(
						useConnections.queryOptions(orgId, {
							connectorKey: params.connectorKey,
						}),
					);
				}
			})
			.catch(() => {
				// Page handles auth/missing-workspace state; swallow loader errors
				// so the global route error UI doesn't replace the page chrome.
			});
	},
	component: ConnectorIndexPage,
});

function ConnectorIndexPage() {
	const { owner, connectorKey } = Route.useParams();
	return (
		<OwnerWorkspaceGate owner={owner}>
			{({ ownerSlug, organizationId, isWorkspaceLoading }) => (
				<ConnectorBody
					ownerSlug={ownerSlug}
					organizationId={organizationId}
					isWorkspaceLoading={isWorkspaceLoading}
					connectorKey={connectorKey}
				/>
			)}
		</OwnerWorkspaceGate>
	);
}

function ConnectorBody({
	ownerSlug,
	organizationId,
	isWorkspaceLoading,
	connectorKey,
}: {
	ownerSlug: string;
	organizationId: string | null;
	isWorkspaceLoading: boolean;
	connectorKey: string;
