import { Link } from "@tanstack/react-router";
import { ChevronRight, Plus, Search } from "lucide-react";
import { useMemo, useState } from "react";
import { StatusDot } from "@/components/sidebar/status-dot";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Skeleton } from "@/components/ui/skeleton";
import { ViewInMemoryLink } from "@/components/view-in-memory-link";
import { type ConnectionItem, type FeedItem, useFeeds } from "@/lib/api";
import { formatTimeAgo } from "@/lib/format-utils";
import { cn } from "@/lib/utils";

/** Show the rail's filter box only once the list is long enough to warrant it.
 * Shared with the connector page's connected-sources rail so both behave alike. */
export const RAIL_SEARCH_THRESHOLD = 6;

function feedLabel(feed: FeedItem): string {
	return feed.display_name?.trim() || feed.feed_key;
}

/** A streaming feed is a live chat channel (store=channel_messages), not a
 * scheduled data source — it has no sync clock, so its sub-line describes the
 * channel rather than a "synced Xago" timestamp. */
function isStreamingFeed(feed: FeedItem): boolean {
	return feed.kind === "streaming";
}

function feedSubline(feed: FeedItem): string {
	if (isStreamingFeed(feed)) return "chat channel";
	return feed.last_sync_at
		? `synced ${formatTimeAgo(feed.last_sync_at)}`
		: "not synced yet";
}

/**
 * Left rail listing the connection's feeds, mirroring the memory page's
 * entity-type rail. The active feed (matching the `?feedId=` deep link) is
 * highlighted; an "Overview" entry returns to the connection's runs + settings.
 * For GitHub App connections the install auto-provisions one feed per repo, so
 * this surfaces them without the user deep-linking into each one.
 */
export function ConnectionFeedsRail({
	connection,
	ownerSlug,
	activeFeedId,
}: {
	connection: ConnectionItem;
	ownerSlug: string;
	activeFeedId: number | undefined;
}) {
	const { data: feeds = [], isLoading } = useFeeds(connection.id);
	const [query, setQuery] = useState("");

	const params = {
		owner: ownerSlug,
		connectorKey: connection.connector_key,
		connectionId: String(connection.id),
	};

	const showSearch = feeds.length >= RAIL_SEARCH_THRESHOLD;
	const filteredFeeds = useMemo(() => {
		const q = query.trim().toLowerCase();
		if (!q) return feeds;
		return feeds.filter((feed) => feedLabel(feed).toLowerCase().includes(q));
	}, [feeds, query]);

	return (
		<nav
			aria-label="Feeds"
			className="flex w-full shrink-0 flex-col gap-1 lg:w-52 xl:w-56"
		>
			<div className="flex items-center justify-between gap-2 px-1 pb-1">
				<span className="text-xs font-medium uppercase tracking-wide text-muted-foreground">
					Feeds
				</span>
				<Button
					asChild
					variant="ghost"
					size="sm"
					className="h-6 px-1.5 text-xs"
				>
					<Link
						to="/$owner/connectors/$connectorKey/$connectionId"
						params={params}
						search={{ addFeed: true }}
					>
						<Plus className="h-3.5 w-3.5" />
						Add
					</Link>
				</Button>
			</div>

			{showSearch ? (
				<div className="relative px-1 pb-1">
					<Search className="pointer-events-none absolute left-3 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-muted-foreground" />
					<Input
						value={query}
						onChange={(e) => setQuery(e.target.value)}
						placeholder="Search feeds"
						className="h-8 pl-8 text-sm"
					/>
				</div>
			) : null}

			<Link
				to="/$owner/connectors/$connectorKey/$connectionId"
				params={params}
				search={{}}
				className={cn(
					"group flex items-center gap-2 rounded-lg px-2 py-1.5 text-sm transition-colors",
					activeFeedId === undefined
						? "bg-muted/60 font-medium text-foreground"
						: "text-muted-foreground hover:bg-accent/50 hover:text-foreground",
				)}
			>
				<span className="min-w-0 flex-1 truncate font-medium">Overview</span>
				<ChevronRight className="h-3.5 w-3.5 shrink-0 opacity-0 transition-opacity group-hover:opacity-100" />
			</Link>

			{isLoading ? (
				<div className="flex flex-col gap-1 px-1 py-1">
					<Skeleton className="h-5 w-full" />
					<Skeleton className="h-5 w-2/3" />
				</div>
			) : (
				<ul className="flex flex-col gap-0.5">
					{filteredFeeds.map((feed) => {
						const active = feed.id === activeFeedId;
						return (
							<li key={feed.id}>
								<div
									className={cn(
										"group flex items-center gap-0.5 rounded-lg pr-1 transition-colors",
										active
											? "bg-muted/60 text-foreground"
											: "text-muted-foreground",
									)}
								>
									<Link
										to="/$owner/connectors/$connectorKey/$connectionId"
										params={params}
										search={{ feedId: feed.id }}
										className={cn(
											"flex min-w-0 flex-1 flex-col gap-0.5 rounded-lg px-2 py-1.5 transition-colors hover:bg-accent/50 hover:text-foreground",
											active && "hover:bg-muted/60",
										)}
									>
										<span className="flex items-center gap-2">
											<StatusDot
												tone={
													feed.status === "active"
														? null
														: feed.status === "error"
															? "destructive"
															: "muted"
												}
											/>
											<span className="min-w-0 flex-1 truncate text-sm font-medium">
												{feedLabel(feed)}
											</span>
										</span>
										<span className="truncate pl-4 text-xs text-muted-foreground">
											{feedSubline(feed)}
										</span>
									</Link>
									<ViewInMemoryLink
										ownerSlug={ownerSlug}
										scope={{ kind: "feed", id: feed.id }}
										variant="ghost"
										iconOnly
										title="View feed activity in memory"
										className="h-7 w-7 shrink-0 opacity-0 transition-opacity group-hover:opacity-100"
									/>
								</div>
							</li>
						);
					})}
				</ul>
			)}
		</nav>
	);
}

