	const { isAdmin } = useMembers(organizationId);
	const hasFeeds = Object.keys(connector.feeds_schema ?? {}).length > 0;
	const hasActions = (connector.operations_summary?.total ?? 0) > 0;
	const hasSources = connections.length > 0;

	// The Setup tab owns adding/reconnecting sources (the connect affordance +
	// OAuth accounts) AND the auth config (OAuth app profiles, install method,
	// credentials). The connected sources themselves live in the rail, so this
	// tab manages rather than re-lists them.
	const setup = (
		<div className="space-y-6">
			<MainConnectorSurface
				connector={connector}
				organizationId={organizationId}
				ownerSlug={ownerSlug}
				connectorKey={connectorKey}
				connections={connections}
				isLoading={isLoading}
				refetchConnections={refetchConnections}
			/>
			<ConnectorSetup connector={connector} organizationId={organizationId} />
		</div>
	);

	// Setup / Feeds / Actions are connector-level facts, so the tab bar shows the
	// same whether or not a source is connected yet — a fresh connector still
	// surfaces what it provides (Feeds) and can do (Actions), so the page never
	// reads as empty pre-connection. The connected-sources rail is the only
	// source-dependent chrome: it appears once there's at least one connection.
	return (
		<ConnectorPageShell
			header={hero}
			tabs={[
				{ value: "setup", label: "Setup" },
				...(hasFeeds ? [{ value: "feeds", label: "Feeds" }] : []),
				...(hasActions && isAdmin
					? [{ value: "actions", label: "Actions" }]
					: []),
			]}
			defaultTab="setup"
			rail={
				hasSources ? (
					<ConnectorSourcesRail
						connections={connections}
						connectorDef={connector}
						ownerSlug={ownerSlug}
						connectorKey={connectorKey}
					/>
				) : undefined
			}
			// The rail case used to render unconstrained, so connecting a first
			// source visibly shifted the page left. Both cases now share the wide
			// column: the rail sits inside it instead of widening the page.
			width={hasSources ? "6xl" : "3xl"}
		>
			<TabsContent value="setup" className="mt-0">
				{setup}
			</TabsContent>

			{hasFeeds ? (
				<TabsContent value="feeds" className="mt-0">
					<AvailableFeedsSection connector={connector} />
				</TabsContent>
			) : null}

			{hasActions && isAdmin ? (
				<TabsContent value="actions" className="mt-0">
					<ConnectorActionsSection
						connector={connector}
						organizationId={organizationId}
					/>
				</TabsContent>
			) : null}
		</ConnectorPageShell>
	);
}

