	const navigate = useNavigate();
	const { tab } = Route.useSearch();
	const activeTab = tab ?? "overview";
	const { isAdmin } = useMembers(organizationId);
	const hasFeeds = Object.keys(connector.feeds_schema ?? {}).length > 0;
	const hasActions = (connector.operations_summary?.total ?? 0) > 0;

	return (
		<ConnectorPageShell
			header={hero}
			tabs={CONNECTOR_TABS.map((t) => ({
				value: t.value,
