				disabled:
					(t.value === "feeds" && !hasFeeds) ||
					(t.value === "actions" && (!hasActions || !isAdmin)),
			}))}
			value={activeTab}
			onValueChange={(next) =>
				void navigate({
					to: "/$owner/connectors/$connectorKey",
					params: { owner: ownerSlug, connectorKey },
					search: { tab: next === "overview" ? undefined : parseConnectorTab(next) },
					replace: true,
				})
			}
			// The rail is always mounted so the content column keeps the same left
			// edge with or without connections — an appearing rail used to shove the
			// page sideways. It renders its own empty state when the list is empty.
			rail={
				<ConnectorSourcesRail
					connections={connections}
					connectorDef={connector}
					ownerSlug={ownerSlug}
					connectorKey={connectorKey}
				/>
			}
			width="6xl"
		>
			<TabsContent value="overview" className="mt-0">
				<MainConnectorSurface
					connector={connector}
					organizationId={organizationId}
					ownerSlug={ownerSlug}
					connectorKey={connectorKey}
					connections={connections}
					isLoading={isLoading}
					refetchConnections={refetchConnections}
				/>
			</TabsContent>

			<TabsContent value="connections" className="mt-0">
				<ConnectionsForConnector
					ownerSlug={ownerSlug}
					connectorKey={connectorKey}
					connections={connections}
					isLoading={isLoading}
				/>
			</TabsContent>

			<TabsContent value="feeds" className="mt-0">
				{hasFeeds ? (
					<AvailableFeedsSection connector={connector} />
				) : (
					<TabEmptyState
						icon={Plug}
						title="No feeds"
						description="This connector doesn't provide any feeds."
					/>
				)}
			</TabsContent>

			<TabsContent value="actions" className="mt-0">
				{hasActions && isAdmin ? (
					<ConnectorActionsSection
						connector={connector}
						organizationId={organizationId}
					/>
				) : (
					<TabEmptyState
						icon={Plug}
						title="No actions"
						description={
							hasActions
								? "Only workspace admins can view connector actions."
								: "This connector doesn't provide any actions."
						}
					/>
				)}
			</TabsContent>

			{/* Connector-level Settings = how this workspace authenticates to the
			    connector. The connection page's Settings tab is the same idea one
			    level down: how *that* connection is configured. */}
			<TabsContent value="settings" className="mt-0">
				<ConnectorSetup connector={connector} organizationId={organizationId} />
			</TabsContent>
		</ConnectorPageShell>
	);
}

