63	export const Route = createFileRoute("/$owner/connectors/$connectorKey/")({
64		validateSearch: (search: Record<string, unknown>) =>
65			pruneSearch({
66				tab: search.tab === undefined ? undefined : parseConnectorTab(search.tab),
67			}),
68		// Fire-and-forget prefetch — workspace warms the cache, the page mounts
69		// on the first frame and ConnectorBody renders its own skeleton while
70		// workspace + connector defs resolve. The connector-defs/connections
71		// prefetches can only fire once workspace lands (they need orgId), so we
72		// chain them via `.then` instead of awaiting — all happen, none block paint.
73		loader: ({ context: { queryClient }, params }) => {
74			void queryClient
75				.fetchQuery(
76					useWorkspaceRoot.queryOptions(params.owner, { slug: params.owner }),
77				)
78				.then((ws) => {
79					const orgId = ws?.workspace?.id;
80					if (orgId) {
81						void queryClient.prefetchQuery(
82							useInstallableConnectorCatalog.queryOptions(orgId),
83						);
84						void queryClient.prefetchQuery(
85							useConnections.queryOptions(orgId, {
86								connectorKey: params.connectorKey,
87							}),
88						);
89					}
90				})
91				.catch(() => {
92					// Page handles auth/missing-workspace state; swallow loader errors
93					// so the global route error UI doesn't replace the page chrome.
94				});
95		},
96		component: ConnectorIndexPage,
97	});
98	
99	function ConnectorIndexPage() {
100		const { owner, connectorKey } = Route.useParams();
101		return (
102			<OwnerWorkspaceGate owner={owner}>
103				{({ ownerSlug, organizationId, isWorkspaceLoading }) => (
104					<ConnectorBody
105						ownerSlug={ownerSlug}
106						organizationId={organizationId}
107						isWorkspaceLoading={isWorkspaceLoading}
108						connectorKey={connectorKey}
109					/>
110				)}
111			</OwnerWorkspaceGate>
112		);
113	}
114	
115	function ConnectorBody({
116		ownerSlug,
117		organizationId,
118		isWorkspaceLoading,
119		connectorKey,
120	}: {
121		ownerSlug: string;
122		organizationId: string | null;
123		isWorkspaceLoading: boolean;
124		connectorKey: string;
125	}) {
126		// Resolve against the full installable catalog (not just installed defs) so
127		// a bundled-but-not-yet-installed connector — e.g. the managed-chat Slack
128		// connector reached from the catalog card — still resolves and renders its
129		// install affordance instead of the "not installed, details unavailable"
130		// dead end.
131		const { data: connectorDefs = [], isLoading: isDefsLoading } =
132			useInstallableConnectorCatalog(organizationId ?? "");
133		const {
134			data: connections = [],
135			isLoading: isConnectionsLoading,
136			refetch: refetchConnections,
137		} = useConnections(organizationId ?? "", { connectorKey });
138		const connector = useMemo(
139			() => connectorDefs.find((def) => def.key === connectorKey),
140			[connectorDefs, connectorKey],
141		);
142	
143		// The connection's stored connector_name is the fallback display when no
144		// definition is installed (orphaned connector, or a connection created
145		// outside the install flow) — same def-or-fallback resolution the Connectors
146		// list uses, so the page never dead-ends on a missing definition.
147		const display = useMemo(
148			() =>
149				resolveConnectorDisplay(connectorKey, connectorDefs, {
150					name: connections[0]?.connector_name ?? connectorKey,
151				}),
152			[connectorKey, connectorDefs, connections],
153		);
154	
155		if (isWorkspaceLoading || isDefsLoading) {
156			// Skeleton mirrors `<ConnectorInfo>` shape (connector-panels.tsx:303):
157			// icon + name row, description card, auth + feeds + actions panels.
158			// Each panel reserves its loaded footprint so the page doesn't
159			// shift when data arrives.
160			return (
161				<div>
162					<div className="mx-auto w-full max-w-3xl space-y-4">
163						<div className="flex items-center gap-2">
164							<Skeleton className="h-6 w-6 rounded" />
165							<Skeleton className="h-5 w-40" />
166						</div>
167						<Skeleton className="h-16 w-full rounded-lg" />
168						<Skeleton className="h-24 w-full rounded-lg" />
169						<Skeleton className="h-32 w-full rounded-lg" />
170					</div>
171				</div>
172			);
173		}
174	
175		const hero = connector ? (
176			<ConnectorHero connector={connector} ownerSlug={ownerSlug} />
177		) : (
178			<div className="space-y-3">
179				<ConnectorDisplay
180					connector={display}
181					showDescription={false}
