import { ChevronRight } from "lucide-react";
import type { ReactNode } from "react";

/** Shared class for a breadcrumb segment that links to an ancestor. */
export const DETAIL_CRUMB_LINK_CLASS =
	"min-w-0 truncate text-xs text-muted-foreground transition-colors hover:text-foreground hover:underline";

/**
 * The `Connectors › Gmail` ancestor trail above a detail title.
 *
 * Every ancestor is a segment, so depth is visible at a glance and any level is
 * one click away. This replaces the old single `back` slot, which showed one hop
 * and — at the feed level — pointed two levels up while the *title* silently
 * carried the link to the level in between.
 *
 * The trail stops at the parent: the <h1> directly beneath it already names the
 * current page, so repeating it as a final crumb only renders the same words
 * twice in a row.
 *
 * Callers pass rendered <Link>s (styled with DETAIL_CRUMB_LINK_CLASS) so this
 * component stays route-agnostic.
 */
export function DetailBreadcrumb({ crumbs }: { crumbs: ReactNode[] }) {
	if (crumbs.length === 0) return null;
	return (
		<nav aria-label="Breadcrumb" className="flex min-w-0 items-center gap-1">
			{crumbs.map((crumb, i) => (
				// Crumbs are a positional trail with no stable id of their own; the
				// list is fixed-length per page and never reordered.
				// biome-ignore lint/suspicious/noArrayIndexKey: positional by nature
				<span key={i} className="flex min-w-0 items-center gap-1">
					{i > 0 ? (
						<ChevronRight className="h-3 w-3 shrink-0 text-muted-foreground/60" />
					) : null}
					{crumb}
				</span>
			))}
		</nav>
	);
}

/**
 * Shared header for the connector / connection / feed detail pages so all three
 * levels look identical: a breadcrumb row, then a title row (title · subtitle ·
 * status, baseline-aligned), then an optional chips row, then an optional error
 * banner. Each page passes its own slots; the layout is the single source of
 * truth so spacing and alignment never drift between pages.
 *
 * `breadcrumb` is rendered as a plain element (typically <DetailBreadcrumb>) so
 * callers own their own routes and this component stays navigation-agnostic.
 */
export function DetailHeader({
	breadcrumb,
	icon,
	title,
	badge,
	status,
	meta,
	caption,
	captionTone = "muted",
}: {
	/** The ancestor trail. Typically a <DetailBreadcrumb>. */
	breadcrumb?: ReactNode;
	/** Leading mark, same size at every level (the connector's logo). */
	icon?: ReactNode;
	/** The primary heading. */
	title: ReactNode;
	/** Small badge trailing the title — a version, a credential mode. */
	badge?: ReactNode;
	/** Status badge shown inline after the badge. */
	status?: ReactNode;
	/** Right-aligned metadata on the title row (e.g. sync/next/events stats). */
	meta?: ReactNode;
	/**
	 * The single line under the title: a description on a connector, an error
	 * or capability summary on a connection. One slot rather than separate
	 * chips/error rows, so the block is the same three rows at every level and
	 * descending never grows or shrinks the header.
	 */
	caption?: ReactNode;
	/** Render the caption as an error rather than muted prose. */
	captionTone?: "muted" | "error";
}) {
	return (
		<div className="flex flex-col gap-2">
			{breadcrumb ? <div className="flex min-w-0">{breadcrumb}</div> : null}
			<div className="flex flex-wrap items-center justify-between gap-x-3 gap-y-1">
				<div className="flex min-w-0 flex-wrap items-center gap-x-3 gap-y-1">
					{icon}
					{typeof title === "string" ? (
						<h1 className="text-2xl font-semibold leading-tight">{title}</h1>
					) : (
						title
					)}
					{badge}
					{status}
				</div>
				{meta ? (
					<div className="flex flex-wrap items-center gap-x-4 gap-y-1 text-xs text-muted-foreground">
						{meta}
					</div>
				) : null}
			</div>
			{/* Always rendered so the header keeps its row count even when a level
			    has nothing to say here. */}
			<p
				className={cn(
					"min-h-[1.25rem] text-sm",
					captionTone === "error" ? "text-destructive" : "text-muted-foreground",
				)}
			>
				{caption}
			</p>
		</div>
	);
}

