}

/**
 * The `Feeds` tab body on a connection: the feeds this connection actually has,
 * as opposed to the connector-level tab which lists what the connector offers.
 * Same tab, same position — the scope narrows as you descend.
 */
export function ConnectionFeedsList({
	connection,
	ownerSlug,
	connectorKey,
}: {
	connection: ConnectionItem;
	ownerSlug: string;
	connectorKey: string;
}) {
	const { data: feeds = [], isLoading } = useFeeds(connection.id);

	const params = {
		owner: ownerSlug,
		connectorKey,
		connectionId: String(connection.id),
	};

	if (isLoading) {
		return (
			<div className="flex flex-col gap-2">
				<Skeleton className="h-12 w-full rounded-lg" />
				<Skeleton className="h-12 w-full rounded-lg" />
			</div>
		);
	}

	if (feeds.length === 0) {
		return (
			<TabEmptyState
				icon={Rss}
				title="No feeds"
				description="Add a feed to start collecting data from this connection."
			>
				<Button asChild size="sm">
					<Link
						to="/$owner/connectors/$connectorKey/$connectionId"
						params={params}
						search={{ addFeed: true }}
					>
						<Plus className="h-3.5 w-3.5" />
						Add feed
					</Link>
				</Button>
			</TabEmptyState>
		);
	}

	return (
		<ul className="flex flex-col gap-2">
			{feeds.map((feed) => (
				<li key={feed.id}>
					<Link
						to="/$owner/connectors/$connectorKey/$connectionId"
						params={params}
						search={{ feedId: feed.id }}
						className="flex items-center justify-between gap-3 rounded-lg border border-border px-3 py-2.5 transition-colors hover:bg-accent/50"
					>
						<span className="flex min-w-0 items-center gap-2">
							<StatusDot
								tone={
									feed.status === "active"
										? null
										: feed.status === "error"
											? "destructive"
											: "muted"
								}
							/>
							<span className="min-w-0 truncate text-sm font-medium">
								{feed.display_name?.trim() || feed.feed_key}
							</span>
						</span>
						<span className="shrink-0 text-xs text-muted-foreground">
							{feed.kind === "streaming"
								? "chat channel"
								: feed.last_sync_at
									? `synced ${formatTimeAgo(feed.last_sync_at)}`
									: "not synced yet"}
						</span>
					</Link>
				</li>
			))}
		</ul>
	);
}

