    railWidth: rail ? Math.round(rail.getBoundingClientRect().width) : 0,
    tablistTop: Math.round(tabsEl.getBoundingClientRect().top),
    tabs: [...document.querySelectorAll('[role=tab]')].map(t=>t.innerText.trim()),
  };
};
window.__before = window.__snap();
JSON.stringify(window.__before, null, 1);

const before = window.__before;
