// click the ERROR connection (billing) — previously the worst case
[...document.querySelectorAll('nav[aria-label="Connections"] a')].find(a=>a.innerText.includes('billing')).click();
await new Promise(r=>setTimeout(r,1200));
const afterError = snap();
