    tabsIdentical: JSON.stringify(before.tabs)===JSON.stringify(afterError.tabs),
    headerRowsIdentical: JSON.stringify(before.headerRows)===JSON.stringify(afterError.headerRows),
    headerHeightShift: afterError.headerHeight - before.headerHeight,
    tablistTopShift: afterError.tablistTop - before.tablistTop,
    railLabelSame: before.railLabel === afterError.railLabel,
    railWidthShift: afterError.railWidth - before.railWidth,
    railRowsSame: JSON.stringify(before.railRows)===JSON.stringify(afterError.railRows),
  }
}, null, 1);

const hdr = document.querySelector('nav[aria-label="Breadcrumb"]').closest('div.flex.flex-col');
const active = [...document.querySelectorAll('nav[aria-label="Connections"] a')].filter(a=>a.className.includes('bg-muted'));
JSON.stringify({
  headerText: [...hdr.children].map(c=>c.innerText.replace(/\n/g,' | ')),
  captionColorIsError: getComputedStyle(hdr.children[2]).color,
  railHighlighted: active.map(a=>a.innerText.replace(/\n/g,' ')),
  railItemCount: document.querySelectorAll('nav[aria-label="Connections"] a[href*="/google.gmail/"]').length,
}, null, 1);

