import type { ReactNode } from "react";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { cn } from "@/lib/utils";

/**
 * Page chrome shared by the connector-detail and connection-detail routes:
 * a sticky header, an optional tab bar, an optional left rail, and the content
 * pane. Both routes grew the same shape independently and drifted — three
 * different width rules (max-w-3xl / unconstrained / max-w-6xl) and two header
 * spacings across two files. Centralising the chrome makes that drift
 * impossible; the routes still own their own tabs, rails and content.
 *
 * `tabs` is optional because the feed-detail mode has no tab bar at all, and
 * `rail` is optional because a connector with no connections (or a connection
 * with no feeds) renders a bare column.
 */
export interface ConnectorPageTab {
	value: string;
	label: string;
	/** Tab body. Rendered by the caller inside <TabsContent>. */
	content: ReactNode;
}

export function ConnectorPageShell({
	header,
	tabs,
	defaultTab,
	value,
	onValueChange,
	rail,
	children,
}: {
	/** Breadcrumb + title block. Always sticky. */
	header: ReactNode;
	/** Tab triggers, in order. Omit for modes with no tab bar (feed detail). */
	tabs?: { value: string; label: string; disabled?: boolean }[];
	defaultTab?: string;
	/**
	 * Controlled active tab. Pass with `onValueChange` to keep the tab in the
	 * URL, so it survives navigation between the connector and its connections
	 * instead of silently resetting.
	 */
	value?: string;
	onValueChange?: (value: string) => void;
	/** Left rail — connections or feeds. Omit when there's nothing to list. */
	rail?: ReactNode;
	children: ReactNode;
}) {
	// One sticky treatment for both routes — previously space-y-3 here and
	// space-y-2 on the connection page, for no reason anyone could name.
	const sticky = cn(
		"sticky top-11 z-10 -mx-4 bg-background px-4 pt-1 lg:-mx-6 lg:px-6",
		tabs ? "pb-0" : "pb-3",
	);
	// The sticky background bleeds full-width (-mx) while its contents align to

