const read = () => {
  const rail = document.querySelector('nav[aria-label="Feeds"], nav[aria-label="Connections"]');
  const railActive = rail ? [...rail.querySelectorAll('a')].filter(a=>/bg-muted|font-medium/.test(a.className)).map(a=>a.innerText.split('\n')[0]) : [];
  return {
    url: location.search || '(default)',
    crumbs: [...document.querySelectorAll('nav[aria-label="Breadcrumb"] a')].map(a=>a.innerText),
    h1: document.querySelector('h1')?.innerText,
    activeTab: document.querySelector('[role=tab][data-state=active]')?.innerText.trim(),
    railLabel: rail?.getAttribute('aria-label'),
    railActive,
    railItems: rail ? [...rail.querySelectorAll('a')].map(a=>a.innerText.split('\n')[0]).slice(0,5) : [],
  };
};
JSON.stringify({feedDetail: read()}, null, 1);

