import { Link } from "@tanstack/react-router";
import { Plus, Rss, Search } from "lucide-react";
import { useMemo, useState } from "react";
import { TabEmptyState } from "@/components/entity-tabs/tab-states";
import { StatusDot } from "@/components/sidebar/status-dot";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Skeleton } from "@/components/ui/skeleton";
import {
	type ConnectionItem,
	type ConnectorDefinitionItem,
	useFeeds,
} from "@/lib/api";
import { connectionLabel } from "@/lib/connection-label";
import { formatTimeAgo } from "@/lib/format-utils";

/** Show the rail's filter box only once the list is long enough to warrant it. */
export const RAIL_SEARCH_THRESHOLD = 6;

/**
 * The left rail: the connector's connections, rendered identically on the
 * connector page and on every connection beneath it.
 *
 * It used to swap to a feeds list when you opened a connection, which meant the
 * sibling connections vanished exactly when you might want to switch between
 * them. Keeping one list at both levels makes the rail behave like a file
 * browser sidebar — only the highlight moves as you navigate. Feeds are reached
 * through the Feeds tab instead.
 */
export function ConnectorSourcesRail({
	connections,
	connectorDef,
	ownerSlug,
	connectorKey,
}: {
	connections: ConnectionItem[];
	connectorDef?: ConnectorDefinitionItem;
	ownerSlug: string;
	connectorKey: string;
}) {
	const [query, setQuery] = useState("");
	const showSearch = connections.length >= RAIL_SEARCH_THRESHOLD;

	const labelled = useMemo(
		() =>
			connections.map((connection) => ({
				connection,
				label: connectionLabel({
					...connection,
					connector_name:

				connector_name:
					connection.connector_name ?? connectorDef?.name ?? null,
			}),
		})),
	[connections, connectorDef?.name],
);
const filtered = useMemo(() => {
	const q = query.trim().toLowerCase();
	if (!q) return labelled;
	return labelled.filter((row) => row.label.toLowerCase().includes(q));
}, [labelled, query]);

return (
	<nav
		aria-label="Connections"
		className="flex w-full shrink-0 flex-col gap-1 lg:w-52 xl:w-56"
	>
		<div className="flex items-center justify-between gap-2 px-1 pb-1">
			<span className="text-xs font-medium uppercase tracking-wide text-muted-foreground">
				Connections
			</span>
			<Button
				asChild
				variant="ghost"
				size="sm"
				className="h-6 px-1.5 text-xs"
			>
				<Link
					to="/$owner/connectors/create/$connectorKey"
					params={{ owner: ownerSlug, connectorKey }}
				>
					<Plus className="h-3.5 w-3.5" />
					Add
				</Link>
			</Button>
		</div>

		{showSearch ? (
			<div className="relative px-1 pb-1">
				<Search className="pointer-events-none absolute left-3 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-muted-foreground" />
				<Input
					value={query}
					onChange={(e) => setQuery(e.target.value)}
					placeholder="Search connections"
					className="h-8 pl-8 text-sm"
				/>
			</div>
		) : null}

		{/* Always mounted, so it must say something when empty rather than
		    collapse and drag the content column left. */}
		{labelled.length === 0 ? (
			<p className="px-2 py-1.5 text-xs text-muted-foreground">
				No connections yet.
			</p>
		) : null}

		{filtered.map(({ connection, label }) => {
			const unhealthy =
				connection.status === "error" ||
				connection.status === "revoked" ||
				connection.status === "pending_auth";
			return (
				<Link
					key={connection.id}
					to="/$owner/connectors/$connectorKey/$connectionId"
					params={{
						owner: ownerSlug,
						connectorKey,
						connectionId: String(connection.id),
					}}
					search={{}}
					className="group flex items-center gap-2 rounded-lg px-2 py-1.5 text-sm text-muted-foreground transition-colors hover:bg-accent/50 hover:text-foreground"
					activeProps={{
						className: "bg-muted/60 font-medium text-foreground",
					}}
				>
					<StatusDot
						tone={
							connection.status === "active"
								? null
								: connection.status === "error" ||
										connection.status === "revoked"
									? "destructive"
									: "amber"
						}
					/>
					<span className="min-w-0 flex-1 truncate">{label}</span>
					{unhealthy ? (
						<span className="shrink-0 text-xs text-muted-foreground">
							{connection.status === "pending_auth"
								? "reconnect"
								: connection.status}
						</span>
					) : null}
				</Link>
			);
		})}
	</nav>
);

