/** Statuses that mean a connection needs a human to do something. */
const UNHEALTHY_STATUSES = new Set(["error", "revoked", "pending_auth"]);

/** What a `pending_auth` row should say — "pending_auth" is a wire value. */
const STATUS_LABEL: Record<string, string> = {
	pending_auth: "needs reconnect",
	revoked: "revoked",
	error: "error",
	paused: "paused",
	active: "active",
};

/**
 * The `Overview` tab body on a connector: how this connector is doing across
 * every connection, with the ones needing attention called out first.
 *
 * This tab used to render nothing at all once a connector was healthy — it was
 * the old `Setup` pane, whose job was adding accounts, and it returned null
 * when there was nothing to configure because the rail listed the connections.
 * Renaming it to Overview left it with no content and no purpose.
 */
export function ConnectorOverview({
	connections,
	connectorDef,
	ownerSlug,
	connectorKey,
}: {
	connections: ConnectionItem[];
	connectorDef?: ConnectorDefinitionItem;
	ownerSlug: string;
	connectorKey: string;
}) {
	const unhealthy = connections.filter((c) =>
		UNHEALTHY_STATUSES.has(c.status),
	);
	const feedTotal = connections.reduce((sum, c) => sum + (c.feed_count ?? 0), 0);
	const actionTotal = connectorDef?.operations_summary?.total ?? 0;

	const stats = [
		{ label: "Connections", value: connections.length },
		{ label: "Needs attention", value: unhealthy.length, alert: true },
		{ label: "Feeds", value: feedTotal },
		{ label: "Actions", value: actionTotal },
	];

	return (
		<div className="space-y-6">
			<dl className="grid grid-cols-2 gap-3 sm:grid-cols-4">
				{stats.map((stat) => (
					<div
						key={stat.label}
						className="rounded-lg border border-border px-3 py-2.5"
					>
						<dt className="text-xs text-muted-foreground">{stat.label}</dt>
						<dd
							className={cn(
								"mt-0.5 font-semibold text-xl tabular-nums",
								stat.alert && stat.value > 0
									? "text-destructive"
									: "text-foreground",
							)}
						>
							{stat.value}
						</dd>
					</div>
				))}
			</dl>

			{unhealthy.length > 0 ? (
				<div className="space-y-2">
					<h2 className="text-xs font-medium uppercase tracking-wide text-muted-foreground">
						Needs attention
					</h2>
					<ul className="flex flex-col gap-2">
						{unhealthy.map((connection) => (
							<li key={connection.id}>
								<Link
									to="/$owner/connectors/$connectorKey/$connectionId"
									params={{
										owner: ownerSlug,
										connectorKey,
										connectionId: String(connection.id),
									}}
									search={{}}
									className="flex items-center justify-between gap-3 rounded-lg border border-border px-3 py-2.5 transition-colors hover:bg-accent/50"
								>
									<span className="flex min-w-0 items-center gap-2">
										<StatusDot
											tone={
												connection.status === "error" ||
												connection.status === "revoked"
													? "destructive"
													: "amber"
											}
										/>
										<span className="min-w-0 truncate text-sm font-medium">
											{connectionLabel({
												...connection,
												connector_name:
													connection.connector_name ??
													connectorDef?.name ??
													null,
											})}
										</span>
									</span>
									<span className="shrink-0 text-xs text-muted-foreground">
										{connection.error_message?.trim() ||
											STATUS_LABEL[connection.status] ||
											connection.status}
									</span>
								</Link>
							</li>
						))}
					</ul>
				</div>
			) : (
				<p className="text-sm text-muted-foreground">
					{connections.length > 0
						? "All connections are healthy."
						: "No connections yet."}
				</p>
			)}
		</div>
	);
}

