JSON.stringify({
  windowWidth: window.innerWidth,
  railLeft: Math.round(rr.left), railRight: Math.round(rr.right), railTop: Math.round(rr.top),
  paneLeft: Math.round(pr.left), paneTop: Math.round(pr.top),
  overlaps: rr.right > pr.left && rr.top < pr.bottom && rr.bottom > pr.top,
  bodyScrollsSideways: document.documentElement.scrollWidth > window.innerWidth,
  layout: rr.bottom <= pr.top ? 'STACKED (rail above content)' : 'SIDE-BY-SIDE',
}, null, 1);

// Verify the stacked (<lg) branch by checking the wrapper's class contract
// rather than relying on a real resize.
const rail = document.querySelector('nav[aria-label="Connections"]');
const wrapper = rail.parentElement;
const col = wrapper.parentElement;
JSON.stringify({
  wrapperClass: wrapper.className,
  columnClass: col.className,
  // below lg: no absolute positioning -> normal flow, mb-6, full width => stacks above content
  belowLgBehaviour: /lg:absolute/.test(wrapper.className) && /mb-6/.test(wrapper.className)
    ? 'stacks above content (mb-6, static)' : 'CHECK',
  atLgBehaviour: /lg:right-full/.test(wrapper.className) ? 'hangs in left gutter' : 'CHECK',
  columnIs3xl: /max-w-3xl/.test(col.className),
}, null, 1);

const box = el => { const r = el.getBoundingClientRect(); return {l:Math.round(r.left), r:Math.round(r.right), w:Math.round(r.width)}; };
const hdr = document.querySelector('nav[aria-label="Breadcrumb"]').closest('div.flex.flex-col');
const tabs = document.querySelector('[role=tablist]');
const pane = document.querySelector('[role=tabpanel][data-state=active]');
const rail = document.querySelector('nav[aria-label="Connections"]');
const topnav = [...document.querySelectorAll('nav,header')].find(n=>n.innerText.includes('Sandboxes'));
// widest thing inside the pane
const widest = pane ? [...pane.querySelectorAll('*')].reduce((a,e)=>{
  const r=e.getBoundingClientRect(); return r.width>a.w?{w:Math.round(r.width),l:Math.round(r.left),r:Math.round(r.right),cls:e.className.slice(0,45)}:a;
},{w:0}) : null;
JSON.stringify({
  window: window.innerWidth,
  topNav: topnav ? box(topnav) : null,
  header: box(hdr),
  tabs: box(tabs),
  pane: box(pane),
  widestInPane: widest,
  rail: box(rail),
  MISMATCH: `header ends ${box(hdr).r}, pane content ends ${widest?.r}`,
}, null, 1);

// Walk up from the content column to find the app's real content area.
let el = document.querySelector('nav[aria-label="Breadcrumb"]').closest('.mx-auto');
const chain = [];
while (el && chain.length < 8) {
  const r = el.getBoundingClientRect();
  chain.push({tag: el.tagName, cls: (el.className||'').slice(0,70), l: Math.round(r.left), r: Math.round(r.right), w: Math.round(r.width)});
  el = el.parentElement;
}
JSON.stringify({window: window.innerWidth, chain}, null, 1);

