	// One sticky treatment for both routes — previously space-y-3 here and
	// space-y-2 on the connection page, for no reason anyone could name.
	const sticky =
		"sticky top-11 z-10 -mx-4 bg-background px-4 pt-1 pb-0 lg:-mx-6 lg:px-6";
	// The sticky background bleeds full-width (-mx) while its contents align to
	// the same column as the body, so header, tabs and content share one left
	// edge instead of the header running full-bleed over a centred column.
	//
	// max-w-3xl matches the Connectors list and the rest of the app, so entering
	// a connector no longer shifts the content ~192px left. The rail does NOT
	// widen this column — it hangs in the gutter beside it (see RAIL_GUTTER),
	// which is what keeps the two pages aligned.
	const column = "mx-auto w-full max-w-3xl";

	const body = (
		<div className={cn("relative mt-6", column)}>
			{/* Absolutely positioned on wide screens so the centred column stays put
			    whether or not a rail is present; below lg it stacks above the
			    content instead, where there is no gutter to hang in. */}
			{rail ? (
				<div className="mb-6 lg:absolute lg:right-full lg:top-0 lg:mb-0 lg:mr-6 lg:w-52 xl:w-56">
					{rail}
				</div>
			) : null}
			{/* Never a full-height flex column: that lets an empty state's
			    justify-center float mid-page with dead space below it. */}
			<div className="min-w-0 space-y-6">{children}</div>
		</div>
	);

	return (
		<div className="flex flex-1 flex-col">
			<Tabs
				value={value}
				onValueChange={onValueChange}
				className="flex min-h-0 flex-1 flex-col"
			>
				<div className={sticky}>
					<div className={cn("space-y-3", column)}>
						{header}
						<TabsList>
							{tabs.map((tab) => (
								<TabsTrigger
									key={tab.value}
									value={tab.value}
									disabled={tab.disabled}
								>
									{tab.label}
								</TabsTrigger>
							))}
						</TabsList>
					</div>
				</div>
				{body}
			</Tabs>
		</div>
	);
}

