// Simulate the user's narrower viewport by constraining the app shell,
// then read how the group lays out at that width.
const scroller = document.querySelector('.overflow-y-auto');
const outer = scroller?.parentElement ?? document.body;
const prev = outer.style.width;
outer.style.width = '1100px';
await new Promise(r=>setTimeout(r,400));
const box = el => { const r = el.getBoundingClientRect(); return {l:Math.round(r.left), r:Math.round(r.right), w:Math.round(r.width)}; };
const rail = document.querySelector('nav[aria-label="Connections"]');
const group = rail.parentElement.parentElement;
const pane = [...document.querySelectorAll('[role=tabpanel][data-state=active]')].pop();
const out = {
  simulatedShellWidth: 1100,
  group: box(group),
  rail: box(rail),
  pane: pane?box(pane):null,
  gap: pane ? Math.round(pane.getBoundingClientRect().left - rail.getBoundingClientRect().right) : null,
};
outer.style.width = prev;
JSON.stringify(out, null, 1);

