122	function extractLabelFromDescription(description: string | undefined, fieldName: string): string {
123	  if (!description) return formatLabel(fieldName);
124	  // Strip a trailing parenthetical example. The comma after "e.g." is optional:
125	  // matching only "(e.g., …)" left "(e.g. …)" in place, and the sentence split
126	  // below then cut at the period inside "e.g." — rendering a Gmail field as
127	  // `Gmail label to sync (e`.
128	  const label = description.replace(/\s*\(e\.g\.,?\s.*?\)/gis, '').trim();
129	  // Take the first sentence, but ignore periods that are part of an
