JSON.stringify({
  topNavMid: n.mid,
  headerMid: h.mid, paneMid: p.mid,
  connectorsListMid_target: 1002,
  contentCentred: Math.abs(p.mid - n.mid) <= 4,
  rail: ra,
  railClearOfContent: ra.r <= p.l,
  gap: p.l - ra.r,
}, null, 1);

